// SMS pre-send gate. Pure and synchronous: it sends nothing and keeps no state.
//
// Rules applied (marketing = telemarketing text under the TCPA):
//  - 47 CFR 64.1200(a)(2): an autodialed/AI-driven marketing text needs prior express written
//    consent -> `marketingConsent` must be exactly true.
//  - 47 CFR 64.1200(a)(10) and CTIA: a STOP reply revokes consent. Any `optedOutAt` value blocks
//    marketing; an unparseable value also blocks (fail closed).
//  - 47 CFR 64.1200(c)(1): no telemarketing before 8 a.m. or at/after 9 p.m. at the called
//    party's location. Local time comes from the profile IANA zone. The window includes 08:00 and
//    excludes 21:00. An unknown or invalid zone blocks marketing (never guessed).
//  - CTIA: marketing messages must tell the recipient how to opt out -> body must contain STOP.
//  - Transactional texts (login codes, delivery updates the customer triggered) are not
//    telemarketing: no consent flag, quiet hours or marketing opt-out applies to them.
//    They still need a valid US number and a non-empty body.

const US_NUMBER = /^\+1[2-9]\d{2}[2-9]\d{6}$/;
const WINDOW_START_MINUTE = 8 * 60;
const WINDOW_END_MINUTE = 21 * 60;

function localMinuteOfDay(now, timeZone) {
  let parts;
  try {
    parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hour: "numeric",
      minute: "numeric",
      hourCycle: "h23",
    }).formatToParts(now);
  } catch {
    return null;
  }
  const hour = Number(parts.find((p) => p.type === "hour")?.value);
  const minute = Number(parts.find((p) => p.type === "minute")?.value);
  return Number.isInteger(hour) && Number.isInteger(minute) ? hour * 60 + minute : null;
}

const block = (reason) => ({ allowed: false, reason });

export function checkSms(message, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return block("invalid_time");
  if (!message || typeof message !== "object") return block("invalid_message");
  const { kind, body, to } = message;
  if (kind !== "marketing" && kind !== "transactional") return block("invalid_kind");
  if (typeof body !== "string" || body.trim() === "") return block("empty_body");
  if (!to || typeof to !== "object" || typeof to.phone !== "string" || !US_NUMBER.test(to.phone)) {
    return block("invalid_phone");
  }

  if (kind === "transactional") return { allowed: true, reason: null };

  if (to.optedOutAt !== null && to.optedOutAt !== undefined) return block("opted_out");
  if (to.marketingConsent !== true) return block("no_marketing_consent");

  const minute =
    typeof to.timeZone === "string" && to.timeZone ? localMinuteOfDay(now, to.timeZone) : null;
  if (minute === null) return block("unknown_time_zone");
  if (minute < WINDOW_START_MINUTE || minute >= WINDOW_END_MINUTE) return block("quiet_hours");

  if (!/\bSTOP\b/i.test(body)) return block("missing_opt_out_notice");

  return { allowed: true, reason: null };
}

import assert from "node:assert/strict";
import { checkSms } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/ours-g1-3/bot.mjs";

const to = (o = {}) => ({ phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...o });
const m = (o = {}, kind = "marketing", body = "Sale today! Reply STOP to opt out") => ({ kind, body, to: to(o) });
const r = (msg, iso) => checkSms(msg, new Date(iso)).reason;
// Chicago CDT = UTC-5 in October; CST = UTC-6 after Nov 1 2026.
assert.deepEqual(checkSms(m(), new Date("2026-10-23T17:00:00Z")), { allowed: true, reason: null });
assert.equal(r(m(), "2026-10-23T13:00:00Z"), null);            // 08:00 local included
assert.equal(r(m(), "2026-10-23T12:59:00Z"), "quiet_hours");   // 07:59
assert.equal(r(m(), "2026-10-24T01:59:00Z"), null);            // 20:59
assert.equal(r(m(), "2026-10-24T02:00:00Z"), "quiet_hours");   // 21:00 excluded
assert.equal(r(m(), "2026-11-02T14:00:00Z"), null);            // 08:00 CST after DST end
assert.equal(r(m(), "2026-11-02T13:59:00Z"), "quiet_hours");
assert.equal(r(m({ timeZone: "Pacific/Honolulu" }), "2026-10-23T17:00:00Z"), "quiet_hours"); // 07:00
assert.equal(r(m({ timeZone: "Nope/Zone" }), "2026-10-23T17:00:00Z"), "unknown_time_zone");
assert.equal(r(m({ timeZone: undefined }), "2026-10-23T17:00:00Z"), "unknown_time_zone");
assert.equal(r(m({ marketingConsent: false }), "2026-10-23T17:00:00Z"), "no_marketing_consent");
assert.equal(r(m({ marketingConsent: undefined }), "2026-10-23T17:00:00Z"), "no_marketing_consent");
assert.equal(r(m({ optedOutAt: "2026-10-01T00:00:00Z" }), "2026-10-23T17:00:00Z"), "opted_out");
assert.equal(r(m({ optedOutAt: "garbage" }), "2026-10-23T17:00:00Z"), "opted_out");
assert.equal(r(m({}, "marketing", "Sale today!"), "2026-10-23T17:00:00Z"), "missing_opt_out_notice");
assert.equal(r(m({ phone: "312555" }), "2026-10-23T17:00:00Z"), "invalid_phone");
// Transactional ignores consent, opt-out, quiet hours, zone.
const t = m({ marketingConsent: false, optedOutAt: "2026-10-01T00:00:00Z", timeZone: "bad" }, "transactional", "Code 123456");
assert.equal(r(t, "2026-10-23T08:00:00Z"), null);
assert.equal(r(m({}, "x"), "2026-10-23T17:00:00Z"), "invalid_kind");
assert.equal(r(m({}, "transactional", " "), "2026-10-23T17:00:00Z"), "empty_body");
assert.equal(checkSms(m(), new Date("x")).reason, "invalid_time");
console.log("all ok");
